  margin-top: auto;
  width: 100%;
  z-index: 2;
  position: relative;
}

/* Editorial Section */
.editorial-section {
  max-width: var(--container-max-width);
  margin: 0 auto;
  padding: var(--spacing-xl) var(--spacing-md);
}

.editorial-grid {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.editorial-card {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  aspect-ratio: 4/3;
  display: flex;
  align-items: flex-end;
}

.editorial-card img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 0;
}

.editorial-card::after {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(to top, rgba(18,18,18,0.9) 0%, rgba(18,18,18,0) 100%);
  z-index: 1;
}

.editorial-content {
  position: relative;
  z-index: 2;
  padding: var(--spacing-lg);
  width: 100%;
}

.editorial-content p {
  color: var(--text-secondary);
  margin-bottom: var(--spacing-md);
}

.read-more {
  font-weight: 600;
  text-transform: uppercase;
  font-size: 0.875rem;
  letter-spacing: 1px;
}

/* Footer */
.site-footer {
  background-color: var(--bg-tertiary);
  padding: var(--spacing-xl) var(--spacing-md) var(--spacing-md);
  border-top: 1px solid var(--border-color);
}

.footer-grid {
  max-width: var(--container-max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-xl);
}

.footer-section h2 {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-md);
}

.footer-section p {
  color: var(--text-secondary);
  margin-bottom: var(--spacing-sm);
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: var(--spacing-sm);
}

.footer-links a {
  color: var(--text-secondary);
}

.footer-links a:hover, .footer-links a:focus-visible {
  color: var(--text-primary);
}

/* Newsletter Form */
.newsletter-form {
  display: flex;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-xs);
  flex-wrap: wrap;
}

.newsletter-form input[type="email"] {
  flex-grow: 1;
  padding: 0.75rem;
  background-color: var(--bg-primary);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  border-radius: 4px;
  min-width: 200px;
}

.newsletter-form input[type="email"]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.help-text {
  font-size: 0.875rem;
}

.status-message {
  margin-top: var(--spacing-sm);
  font-size: 0.875rem;
  font-weight: 600;
}

.status-success {
  color: var(--success);
}

.footer-bottom {
  max-width: var(--container-max-width);
  margin: 0 auto;
  text-align: center;
  padding-top: var(--spacing-lg);
  border-top: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 0.875rem;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .header-container {
    flex-wrap: wrap;
  }
  .nav-links {
    order: 3;
    width: 100%;
    margin-top: var(--spacing-md);
    justify-content: center;
    gap: var(--spacing-md);
  }
}

/* Media query to handle reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Setup Add to Cart functionality with basic accessible announcements
  const cartButtons = document.querySelectorAll('.add-to-cart');
  const cartBadge = document.querySelector('.cart-badge');
  let cartCount = 0;

  // Create an aria-live region for screen reader announcements
  const announcer = document.createElement('div');
  announcer.setAttribute('aria-live', 'polite');
  announcer.classList.add('sr-only');
  document.body.appendChild(announcer);

  cartButtons.forEach(button => {
    button.addEventListener('click', (e) => {
      // Prevent the event from bubbling up to the card link
      e.stopPropagation();
      e.preventDefault();

      cartCount++;
      cartBadge.textContent = cartCount;

      // Get the product name for the announcement
      const productName = button.querySelector('.sr-only').textContent;
      announcer.textContent = `${productName} added to cart. You now have ${cartCount} items in your cart.`;

      // Visual feedback
      const originalText = button.innerHTML;
      button.innerHTML = 'Added! <span class="sr-only">to cart</span>';
      setTimeout(() => {
        button.innerHTML = originalText;
      }, 2000);
    });
  });

  // Newsletter Form Handler
  const newsletterForm = document.getElementById('newsletter-form');
  const newsletterStatus = document.getElementById('newsletter-status');

  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('email-input').value;

      if (email) {
        // Simulate an API call
        newsletterForm.querySelector('button').disabled = true;
        newsletterStatus.textContent = 'Subscribing...';
        newsletterStatus.classList.remove('status-success');

        setTimeout(() => {
          newsletterStatus.textContent = 'Thanks for subscribing!';
          newsletterStatus.classList.add('status-success');
          newsletterForm.reset();
          newsletterForm.querySelector('button').disabled = false;
        }, 1000);
      }
    });
  }
});

