  // Setup Add to Cart functionality with basic accessible announcements
  const cartButtons = document.querySelectorAll('.add-to-cart');
  const cartBadge = document.querySelector('.cart-badge');
  let cartCount = 0;

  // Create an aria-live region for screen reader announcements
  const announcer = document.createElement('div');
  announcer.setAttribute('aria-live', 'polite');
  announcer.classList.add('sr-only');
  document.body.appendChild(announcer);

  cartButtons.forEach(button => {
    button.addEventListener('click', (e) => {
      // Prevent the event from bubbling up to the card link
      e.stopPropagation();
      e.preventDefault();

      cartCount++;
      cartBadge.textContent = cartCount;
      const cartButton = document.getElementById('cart-button');
      if (cartButton) {
        cartButton.setAttribute('aria-label', `Shopping Cart with ${cartCount} items`);
      }

      // Get the product name for the announcement
      const productName = button.querySelector('.sr-only').textContent;
      announcer.textContent = `${productName} added to cart. You now have ${cartCount} items in your cart.`;

      // Visual feedback
      const originalText = button.innerHTML;
      button.innerHTML = 'Added! <span class="sr-only">to cart</span>';
      setTimeout(() => {
        button.innerHTML = originalText;
      }, 2000);
    });
  });

  // Newsletter Form Handler
  const newsletterForm = document.getElementById('newsletter-form');
  const newsletterStatus = document.getElementById('newsletter-status');

  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('email-input').value;

      if (email) {
        // Simulate an API call
        newsletterForm.querySelector('button').disabled = true;
        newsletterStatus.textContent = 'Subscribing...';
        newsletterStatus.classList.remove('status-success');

        setTimeout(() => {
          newsletterStatus.textContent = 'Thanks for subscribing!';
          newsletterStatus.classList.add('status-success');
          newsletterForm.reset();
          newsletterForm.querySelector('button').disabled = false;
        }, 1000);
      }
    });
  }
});
